import React, { useEffect, useMemo, useState } from "react";
import Navbar from "../components/Navbar";
import MiniCalendar from "../components/MiniCalendar";
import { useAuth } from "../context/AuthContext";
import "./CalendarPage.css";

const STORAGE_KEY = "campusmobi_calendar_events";

function dateKey(d) {
  return d.toISOString().slice(0, 10);
}

function loadEvents() {
  const raw = localStorage.getItem(STORAGE_KEY);
  if (raw) {
    try {
      return JSON.parse(raw);
    } catch {
      // fall through
    }
  }
  const today = dateKey(new Date());
  const seed = {
    [today]: [
      { id: "e1", time: "09:00", title: "Computer Science — Lecture Hall A" },
      { id: "e2", time: "11:00", title: "Mathematics — Lecture Hall B" },
    ],
  };
  localStorage.setItem(STORAGE_KEY, JSON.stringify(seed));
  return seed;
}

export default function CalendarPage() {
  const { isGuest } = useAuth();
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [events, setEvents] = useState(loadEvents);
  const [time, setTime] = useState("");
  const [title, setTitle] = useState("");

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
  }, [events]);

  const key = dateKey(selectedDate);
  const dayEvents = useMemo(
    () => (events[key] || []).slice().sort((a, b) => a.time.localeCompare(b.time)),
    [events, key]
  );

  function addEvent(e) {
    e.preventDefault();
    if (!title.trim() || !time) return;
    setEvents((prev) => ({
      ...prev,
      [key]: [...(prev[key] || []), { id: "e" + Date.now(), time, title: title.trim() }],
    }));
    setTitle("");
    setTime("");
  }

  function deleteEvent(id) {
    setEvents((prev) => ({ ...prev, [key]: (prev[key] || []).filter((ev) => ev.id !== id) }));
  }

  return (
    <div>
      <Navbar />
      <div className="page-shell">
        <h3 className="section-title">Calendar</h3>
        <div className="cal-layout">
          <MiniCalendar selectedDate={selectedDate} onSelectDate={setSelectedDate} />

          <div className="cal-events-card">
            <div className="cal-events-header">
              <h3>
                {selectedDate.toLocaleDateString("en-US", { weekday: "long", day: "numeric", month: "long" })}
              </h3>
            </div>

            {isGuest ? (
              <p className="cal-empty">Sign in to add or edit calendar events. You can still view today's schedule on the dashboard.</p>
            ) : (
              <form className="event-form" onSubmit={addEvent}>
                <input
                  className="field"
                  type="time"
                  value={time}
                  onChange={(e) => setTime(e.target.value)}
                  required
                />
                <input
                  className="field"
                  type="text"
                  placeholder="Event title ..."
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  required
                />
                <button type="submit" className="btn btn-primary btn-sm">Add</button>
              </form>
            )}

            {dayEvents.length === 0 ? (
              <p className="cal-empty">No events for this day.</p>
            ) : (
              dayEvents.map((ev) => (
                <div className="event-item" key={ev.id}>
                  <span className="event-time">{ev.time}</span>
                  <span className="event-title">{ev.title}</span>
                  {!isGuest && (
                    <button className="event-delete" onClick={() => deleteEvent(ev.id)}>Remove</button>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
